<?php
class PadSignalLimit extends RuntimeException {}
function padSignalTick(&$state,$n=1){if($state['work']+$n>$state['maxWork'])throw new PadSignalLimit('signal work exceeded');$state['work']+=$n;}
function padSignalResultFinite($v){if(is_float($v)&&!is_finite($v))throw new InvalidArgumentException('signal arithmetic exceeds finite range');if(is_array($v))foreach($v as $child)padSignalResultFinite($child);}
function padSignalSamples($values,&$state,$max=4096){if(!is_array($values)||!array_is_list($values)||!$values||count($values)>$max)throw new InvalidArgumentException('samples require 1..'.$max.' values');$out=[];foreach($values as $v){padSignalTick($state);if((!is_int($v)&&!is_float($v))||!is_finite((float)$v))throw new InvalidArgumentException('samples must be finite native numbers');$out[]=(float)$v;}return $out;}
function padSignalRate($options,$required=FALSE){if(!array_key_exists('sampleRate',$options)){if($required)throw new InvalidArgumentException('sampleRate is required');return NULL;}$rate=$options['sampleRate'];if((!is_int($rate)&&!is_float($rate))||!is_finite((float)$rate)||$rate<=0||$rate>1e12)throw new InvalidArgumentException('sampleRate must be in (0,1e12] Hz');return (float)$rate;}
function padSignalWindowCoefficients($n,$name,$periodic,&$state){if(!in_array($name,['rectangular','hann','hamming','blackman'],TRUE)||!is_bool($periodic))throw new InvalidArgumentException('window is rectangular/hann/hamming/blackman; periodic is boolean');$out=[];for($i=0;$i<$n;$i++){padSignalTick($state);$angle=$n===1?0:2*M_PI*$i/($periodic?$n:$n-1);$out[]=$n===1?1.0:match($name){'rectangular'=>1.0,'hann'=>.5-.5*cos($angle),'hamming'=>.54-.46*cos($angle),'blackman'=>.42-.5*cos($angle)+.08*cos(2*$angle)};}return $out;}
function padSignalAccumulate(&$sum,&$correction,$term){if(!is_finite($term))throw new InvalidArgumentException('signal product exceeds finite range');$y=$term-$correction;$next=$sum+$y;$correction=($next-$sum)-$y;$sum=$next;if(!is_finite($sum))throw new InvalidArgumentException('signal sum exceeds finite range');}
